<thead><tr style="background:#f8f7f3"><th style="padding:4px;border:1px solid #ddd">Technician</th><th style="padding:4px;border:1px solid #ddd">Started</th><th style="padding:4px;border:1px solid #ddd">Finished</th><th style="padding:4px;border:1px solid #ddd">Hours</th><th style="padding:4px;border:1px solid #ddd">Rate</th><th style="padding:4px;border:1px solid #ddd">Cost</th></tr></thead>
<tbody>
{% for row in doc.time_logs %}
<tr><td style="padding:4px;border:1px solid #ddd">{{ row.technician }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.started_at }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.finished_at }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.hours }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.hourly_rate }}</td><td style="padding:4px;border:1px solid #ddd">{{ row.labour_cost }}</td></tr>
{% endfor %}
</tbody>
</table>
<h3 style="font-size:12px;margin:12px 0 6px;border-bottom:1px solid #eee;padding-bottom:4px">Consumed Parts</h3>
